export const QIBLA_TEXT_KEYS=Object.freeze(Object.fromEntries(Object.entries(QIBLA_UI_SOURCE).map(([key,value])=>[value,'qiblaUi.'+key])));
export function qiblaPart(value){
 const key=Object.hasOwn(QIBLA_TEXT_KEYS,value)?QIBLA_TEXT_KEYS[value]:null;if(key)return{key,fallback:value};
 const cityPrefix='Центр выбранного города: ';
 if(typeof value==='string'&&value.startsWith(cityPrefix))return{key:'qiblaUi.cityCenter',fallback:value,parameters:{city:value.slice(cityPrefix.length)}};
 return value;
}
export function qiblaMapControls(host){
 const controls=[['.maplibregl-ctrl-zoom-in','zoomIn'],['.maplibregl-ctrl-zoom-out','zoomOut'],['.leaflet-control-zoom-in','zoomMapIn'],['.leaflet-control-zoom-out','zoomMapOut'],['.maplibregl-ctrl-attrib-button','attribution'],['.maplibregl-canvas','mapRegion']];
 for(const[selector,key]of controls){const node=host.querySelector(selector);if(!node)continue;uiAttribute(node,'aria-label','qiblaUi.'+key,QIBLA_UI_SOURCE[key]);if(key!=='mapRegion')uiAttribute(node,'title','qiblaUi.'+key,QIBLA_UI_SOURCE[key]);}
}
